options.helpers:
// Presentation only. Every number is a collector gauge; this code orders,
// words and colours them and never turns a missing reading into a number.
const PROVIDERS = {
  claude: {name: 'Claude', icon: '✳', bg: '#d97757', fg: '#fff'},
  codex: {name: 'Codex', icon: '⊛', bg: '#e8e8e8', fg: '#111'},
  ollama: {name: 'Ollama', icon: '◉', bg: '#f2f2f2', fg: '#111'},
  'opencode-go': {name: 'OpenCode Go', icon: '{}', bg: '#2b2f3a', fg: '#7dd3fc'},
  antigravity: {name: 'Antigravity', icon: 'A', bg: 'linear-gradient(135deg,#4f8cff,#c86bfa)', fg: '#fff'},
  grok: {name: 'Grok', icon: '⊘', bg: '#000', fg: '#fff'},
  commandCode: {name: 'Command Code', icon: 'C', bg: '#2b2f3a', fg: '#e6e8ee'},
  opencode: {name: 'OpenCode Zen', icon: 'O', bg: '#2b2f3a', fg: '#e6e8ee'},
  'cloudflare-workers-ai': {name: 'Cloudflare'},
  'kilo-keyed': {name: 'Kilo (keyed)', icon: 'K'},
  openrouter: {name: 'OpenRouter'},
  nvidia: {name: 'NVIDIA'},
  ovh: {name: 'OVH'},
  zai: {name: 'Zai'},
  deepseek: {name: 'DeepSeek'},
  orcarouter: {name: 'Orcarouter'},
};
function who(id) {
  const known = PROVIDERS[id] || {};
  const text = String(id || '');
  return {
    name: known.name || text.split(/[-_\s]+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
    icon: known.icon || text.charAt(0).toUpperCase(),
    bg: known.bg || '#2b2f3a',
    fg: known.fg || '#e6e8ee',
  };
}
function num(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function round1(value) { return Math.round(value * 10) / 10; }
// The span until a reset: minutes, hours, then days.
function span(seconds) {
  if (seconds <= 0) { return 'now'; }
  const minutes = Math.max(1, Math.round(seconds / 60));
  if (minutes < 60) { return minutes + 'm'; }
  if (minutes < 2880) { return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm'; }
  return round1(minutes / 1440) + 'd';
}
function back(reset, now) {
  if (reset === null || reset === undefined) { return ''; }
  const left = span(reset - now);
  return left === 'now' ? 'back now' : 'back in ' + left;
}
// The share that is left: a half point is kept, a whole reading has no zero.
function share(left) {
  const tenths = Math.round(left * 1000);
  return (tenths % 10 === 0 ? String(tenths / 10) : (tenths / 10).toFixed(1)) + '%';
}
function signed(points) {
  const value = round1(Math.abs(points));
  return (points > 0 ? '+' : points < 0 ? '−' : '') + value;
}
function clock(seconds) {
  const moment = new Date(seconds * 1000);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad = (n) => String(n).padStart(2, '0');
  return moment.getUTCDate() + ' ' + months[moment.getUTCMonth()] + ' ' + pad(moment.getUTCHours()) + ':' + pad(moment.getUTCMinutes()) + 'Z';
}
// A pace band to a tone and a word. spent is out of quota, never "on pace".
const PACE = {
  ahead: {tone: 'good', word: 'ahead of pace'},
  on_pace: {tone: 'ok', word: 'on pace'},
  behind: {tone: 'warn', word: 'behind pace'},
  far_behind: {tone: 'bad', word: 'overspent'},
  spent: {tone: 'out', word: 'out of quota'},
};
// The bar of Paced Availability: centre line is on pace, right is ahead and
// left is overspent. A missing reading gets no bar and no number.
function paBar(points) {
  if (points === null) { return {known: false, left: 50, width: 0, side: 'unk'}; }
  const half = Math.min(100, Math.abs(points)) / 2;
  return {known: true, left: points < 0 ? 50 - half : 50, width: Math.max(half, 1.5), side: points < 0 ? 'neg' : 'pos'};
}

// Who fills a reading the collector does not publish yet: the sub-issue of the epic.
const FILLED_BY = {claude: '#465', commandCode: '#466'};
function filledBy(provider) { return FILLED_BY[provider] ? ' · ' + FILLED_BY[provider] : ''; }

function ordinal(n) {
  const rest = n % 100;
  const suffix = rest >= 11 && rest <= 13 ? 'th' : ({1: 'st', 2: 'nd', 3: 'rd'}[n % 10] || 'th');
  return n + suffix;
}
// The model id the calibration series names: a path separator and an at sign become an underscore.
function calibrationKey(provider, model) { return provider + '|' + String(model || '').replace(/[@/]/g, '_'); }

// ---- Routes: one row per selected route of a lane --------------------------
const ROUTE_FIELDS = {position: 'position', left: 'left', pace: 'pace', resetAt: 'resetAt'};
function readRoutes(rows) {
  const routes = new Map();
  for (const row of rows || []) {
    if (!row || !row.category || !row.provider || !row.model || !ROUTE_FIELDS[row.field]) { continue; }
    const key = [row.category, row.provider, row.model, row.effort || ''].join('|');
    let route = routes.get(key);
    if (!route) { route = {labels: row, n: {}}; routes.set(key, route); }
    route.n[row.field] = num(row.value);
  }
  return Array.from(routes.values());
}
// What a route is, in the order the picker ranks it, and why.
function routeView(route, now) {
  const l = route.labels;
  const n = route.n;
  const inferred = l.window === 'inferred';
  // An inferred window that has seen no limit is not 100%: it is unknown.
  const left = n.left === undefined || n.left === null || (inferred && n.left >= 1) ? null : n.left;
  const pace = PACE[l.pace_state] || null;
  const pa = n.pace === undefined || n.pace === null ? null : n.pace;
  const out = l.state === 'exhausted' || l.state === 'excluded' || l.state === 'unavailable';
  let kind = 'ok';
  let word = '';
  if (l.state === 'exhausted') { kind = 'out'; word = 'Out of quota'; }
  else if (l.state === 'excluded') { kind = 'out'; word = 'Excluded'; }
  else if (l.state === 'unavailable') { kind = 'out'; word = 'Unavailable'; }
  else if (l.state === 'reserved') { kind = 'held'; word = 'Held for review'; }
  else if (l.overspent === 'true' || l.pace_state === 'far_behind') { kind = 'bad'; word = 'Overspent'; }
  else if (l.pace_state === 'behind') { kind = 'warn'; word = 'Behind pace'; }
  else if (left === null && pa === null) { kind = 'unk'; }
  else if (pace) { kind = pace.tone; }
  const reset = n.resetAt === undefined ? null : n.resetAt;
  const provider = who(l.provider);
  const bar = paBar(out ? null : pa);
  return {
    key: [l.category, l.provider, l.model].join(':'),
    provider: l.provider, name: provider.name, icon: provider.icon, bg: provider.bg, fg: provider.fg,
    model: l.display_name || l.model, rawModel: l.model, effort: l.effort || '',
    position: n.position === undefined || n.position === null ? 1e9 : n.position,
    state: l.state, kind: kind, word: word, out: out,
    left: left, leftText: left === null ? '' : share(left),
    // spent routes say 0% left because the quota is gone, not because it is unknown
    // a daily or session window has no pace: only a long window is paced
    paceLong: pa !== null || out || /week|month|quota/i.test(l.window || ''),
    capacity: left === null ? (out ? '' : (inferred ? 'no limit seen' : 'capacity unknown' + filledBy(l.provider))) : share(left) + ' left',
    pa: pa, paText: out || pa === null ? '' : signed(pa), paKnown: bar.known && !out,
    paLeft: bar.left, paWidth: bar.width, paSide: bar.side,
    window: l.window || '', reset: reset,
    when: reset === null ? '' : (out ? back(reset, now) : (span(reset - now) === 'now' ? 'resets now' : 'resets in ' + span(reset - now))),
    estimated: inferred && left !== null,
    free: /^(free|promotion)$/.test(l.billing || ''),
    note: l.state === 'reserved' ? 'review headroom unknown' : '',
    untrusted: l.trust === 'untrusted',
    limited: l.sensitivity_sensitive === 'false',
  };
}
function laneRows(rows, now, free) {
  const views = readRoutes(rows).map((route) => routeView(route, now))
    .sort((a, b) => a.position - b.position || (a.name < b.name ? -1 : 1));
  const next = views.findIndex((view) => !view.out && view.kind !== 'held');
  return views.map((view, index) => ({...view, rank: index + 1, next: index === next}));
}

// ---- Account windows and calibration: readings joined to a provider's selected route ----
// An account whose lowest window reads zero is out of quota, whatever its route reading says.
function readAccounts(rows) {
  const accounts = new Map();
  for (const row of rows || []) {
    if (!row || !row.account || (row.field !== 'acctLeft' && row.field !== 'acctReset')) { continue; }
    const key = row.account + '|' + (row.quota_id || row.kind || '');
    let window = accounts.get(row.account);
    if (!window) { window = new Map(); accounts.set(row.account, window); }
    let entry = window.get(key);
    if (!entry) { entry = {left: null, reset: null, estimated: row.evidence === 'inferred'}; window.set(key, entry); }
    if (row.field === 'acctLeft') { entry.left = num(row.value); } else { entry.reset = num(row.value); }
  }
  const out = new Map();
  for (const [account, windows] of accounts) {
    const spent = Array.from(windows.values()).filter((w) => w.left !== null && w.left <= 0);
    if (spent.length) { out.set(account, {reset: Math.max(...spent.map((w) => w.reset || 0)) || null, estimated: spent.every((w) => w.estimated)}); }
  }
  return out;
}
const CALIBRATION = {
  ok: {tone: 'good', word: 'calibrated', hint: 'the limit reading has matched the provider so far'},
  warn: {tone: 'warn', word: 'calibration warning', hint: 'the provider refused while the reading showed headroom'},
  fail: {tone: 'bad', word: 'calibration failed', hint: 'the provider refused on consecutive days while the reading showed headroom'},
  unmeasured: {tone: 'unk', word: 'not calibrated yet', hint: 'no refusal or success has been counted for this route yet'},
};
function readCalibration(rows) {
  const states = new Map();
  for (const row of rows || []) {
    if (row && row.field === 'calibration' && row.provider && CALIBRATION[row.state]) { states.set(calibrationKey(row.provider, row.model), row.state); }
  }
  return states;
}

// ---- Census: every candidate route, counted by the one reason it is or is not picked ----
const REASONS = [
  {key: 'pickable', label: 'Pickable', tone: 'good', hint: 'available and not overspent'},
  {key: 'overspent', label: 'Overspent', tone: 'bad', hint: 'spending far faster than its allowance pace'},
  {key: 'exhausted', label: 'Out of quota', tone: 'out', hint: 'its allowance is spent until the reset'},
  {key: 'untrusted', label: 'Untrusted', tone: 'trust', hint: 'a verified outcome contradicted the route'},
  {key: 'held', label: 'Held for review', tone: 'held', hint: 'headroom is reserved for review work'},
  {key: 'cooling', label: 'Cooling down', tone: 'warn', hint: 'rate limited until a recorded time'},
  {key: 'unavailable', label: 'Not offered', tone: 'idle', hint: 'the T3 instance does not offer the route'},
  {key: 'obsolete', label: 'Obsolete', tone: 'idle', hint: 'deprecated or superseded within its family (label from #469)'},
  {key: 'excluded', label: 'Excluded by policy', tone: 'idle', hint: 'the owner policy excludes the route'},
  {key: 'public', label: 'Public pool', tone: 'idle', hint: 'free but not on the owner-approved list, so never picked'},
];
// The first reason that applies: a route is counted once.
function routeReason(l) {
  const reason = String(l.reason || '');
  if (l.trust === 'excluded' || l.state === 'excluded') { return 'excluded'; }
  // The collector's obsolete label wins; the reason text is the fallback until every route carries it.
  if (l.obsolete === 'true' || /obsolete|deprecated|superseded/i.test(reason)) { return 'obsolete'; }
  // OpenCode Free publishes its billing as unknown: a route of its pool that is not on the owner-approved list is public pool too.
  const free = /^(free|promotion)$/.test(l.billing || '') || /^opencode-free:/.test(l.pool || '');
  if (free && l.approved_free === 'false') { return 'public'; }
  if (l.state === 'unavailable') { return /cooling/i.test(reason) ? 'cooling' : 'unavailable'; }
  if (l.state === 'exhausted') { return 'exhausted'; }
  if (l.trust === 'untrusted') { return 'untrusted'; }
  if (l.state === 'reserved') { return 'held'; }
  if (l.overspent === 'true' || l.pace_state === 'far_behind') { return 'overspent'; }
  return 'pickable';
}
function readCensus(rows, category) {
  const providers = new Map();
  for (const row of rows || []) {
    if (!row || row.field !== 'census' || !row.provider || (category && row.category !== category)) { continue; }
    const count = num(row.value);
    if (count === null || count <= 0) { continue; }
    let entry = providers.get(row.provider);
    if (!entry) { entry = {provider: row.provider, total: 0, limited: 0, by: {}}; providers.set(row.provider, entry); }
    const key = routeReason(row);
    entry.by[key] = (entry.by[key] || 0) + count;
    entry.total += count;
    if (row.sensitivity_sensitive === 'false') { entry.limited += count; }
  }
  return providers;
}
function censusView(entry) {
  if (!entry) { return null; }
  const parts = REASONS.filter((reason) => entry.by[reason.key]).map((reason) => ({
    key: reason.key, label: reason.label, tone: reason.tone, count: entry.by[reason.key],
    pct: Math.round(entry.by[reason.key] * 1000 / entry.total) / 10}));
  const skipped = parts.filter((part) => part.key !== 'pickable');
  return {total: entry.total, pickable: entry.by.pickable || 0, parts: parts, limited: entry.limited,
    partial: entry.limited > 0 && entry.limited < entry.total,
    text: (entry.by.pickable || 0) + ' of ' + entry.total + ' pickable',
    skipped: skipped.map((part) => part.count + ' ' + part.label.toLowerCase()).join(' · ')};
}

// ---- Lanes: one row per provider, its selected route and why its other routes are skipped ----
const NOW = (value) => (num(value) || 0) / 1000;
function providerRoute(view, census, account, calibration, now) {
  if (view) {
    const routed = {...view, census: censusView(census)};
    if (calibration) { routed.calib = calibration; }
    if (account && !view.out) {
      // The provider's account says it is spent: show that, with the window's reset, not the route's own reading.
      return {...routed, kind: 'out', out: true, word: 'Out of quota', capacity: '0% left', leftText: '0%', left: 0,
        paKnown: false, paceLong: false, when: account.reset ? back(account.reset, now) : '',
        acctNote: 'account window spent' + (account.estimated ? ' · estimated' : '')};
    }
    return routed;
  }
  const stub = censusView(census);
  const top = stub && stub.parts.filter((part) => part.key !== 'pickable').sort((a, b) => b.count - a.count)[0];
  const identity = who(census.provider);
  // Routes that can be picked but none is selected: unknown, not out. Only a provider with nothing pickable is out.
  const open = !!(stub && stub.pickable > 0);
  // A spent account blocks every route of the provider, selected or not.
  if (account) {
    return {provider: census.provider, name: identity.name, icon: identity.icon, bg: identity.bg, fg: identity.fg,
      model: '', noRoute: true, paceLong: false, kind: 'out', out: true, word: 'Out of quota', capacity: '', leftText: '',
      paKnown: false, paText: '', paLeft: 50, paWidth: 0, paSide: 'unk', when: account.reset ? back(account.reset, now) : '',
      acctNote: 'account window spent' + (account.estimated ? ' · estimated' : ''), position: 1e9, next: false, census: stub};
  }
  return {provider: census.provider, name: identity.name, icon: identity.icon, bg: identity.bg, fg: identity.fg,
    model: '', noRoute: true, paceLong: false, kind: open ? 'unk' : 'out', out: !open,
    word: open ? '' : (top ? 'All ' + top.label.toLowerCase() : 'No route'),
    capacity: open ? 'no route selected' : '', leftText: '', paKnown: false, paText: '', paLeft: 50, paWidth: 0, paSide: 'unk', when: '',
    position: 1e9, next: false, census: stub};
}
// The orchestrator is the picker's first orchestrator: the other candidates it lists are not orchestrators.
function configured(rows) {
  const list = (rows || []).filter((row) => row && row.category === 'orchestrator' && row.field === 'position');
  if (!list.length) { return rows; }
  const first = list.reduce((a, b) => (num(b.value) < num(a.value) ? b : a));
  return rows.filter((row) => !row || row.category !== 'orchestrator' || row.provider === first.provider);
}
function laneProviders(rows, now, lane) {
  const category = lane === 'orchestrator' ? 'orchestrator' : 'worker';
  const selected = new Map();
  // One route per provider: the picker's own order decides when two routes of a provider are selected.
  for (const route of readRoutes((rows || []).filter((row) => row && row.category === category))) {
    const view = routeView(route, now);
    const known = selected.get(route.labels.provider);
    if (!known || view.position < known.position) { selected.set(route.labels.provider, view); }
  }
  const census = readCensus(rows, category);
  const accounts = lane === 'free' ? readAccounts(rows) : new Map();
  const calibration = lane === 'free' ? readCalibration(rows) : new Map();
  // A provider whose every route is in the public pool has no approved worker: it is counted, never listed.
  const listed = Array.from(census.keys()).filter((provider) => {
    const entry = census.get(provider);
    return lane !== 'free' || selected.has(provider) || entry.by.public !== entry.total;
  });
  const providers = new Set([...selected.keys(), ...listed]);
  const list = Array.from(providers).map((provider) => {
    const view = selected.get(provider);
    const state = view ? calibration.get(calibrationKey(provider, view.rawModel)) : null;
    return providerRoute(view, census.get(provider), accounts.get(provider),
      state ? {...CALIBRATION[state], state: state} : null, now);
  });
  list.sort((a, b) => a.position - b.position || (b.census ? b.census.total : 0) - (a.census ? a.census.total : 0)
    || (a.name < b.name ? -1 : 1));
  const first = list.findIndex((view) => !view.noRoute && !view.out && view.kind !== 'held');
  // The rank is the picker's own position among all workers, so a paid worker reads 4th when free routes go first.
  return list.map((view, index) => ({...view, rank: view.position < 1e9 ? view.position : '·', first: index === first,
    next: index === first && view.position === 1, many: !!(view.census && view.census.total > 1),
    pace: !view.noRoute && !view.acctNote && (view.paKnown || (view.kind !== 'unk' && (view.paceLong || !!view.when)))}));
}
context.handlebars.registerHelper('modelRows', function(rows, now, lane, limit) {
  const all = laneProviders(configured(rows), NOW(now), lane);
  const shown = limit ? all.slice(0, limit) : all;
  return {rows: shown, more: all.length - shown.length, count: all.length};
});
// ---- Summary tiles ----
function nextRoute(rows, now, lane) {
  const view = laneProviders(rows, now, lane).find((entry) => entry.first);
  if (!view) { return null; }
  // A paid worker is tried after the free routes: say where the picker puts it.
  const order = lane === 'paid' && view.position > 1 && view.position < 1e9 ? 'tried ' + ordinal(view.position) + ', after the free routes' : '';
  return {name: view.name, icon: view.icon, bg: view.bg, fg: view.fg, model: view.model, kind: view.kind,
    detail: [view.word, view.capacity, view.when, order].filter(Boolean).join(' · ')};
}
context.handlebars.registerHelper('modelSummary', function(rows, now, scope) {
  rows = configured(rows);
  const at = NOW(now);
  const census = new Map();
  let total = 0;
  let pickable = 0;
  let limited = 0;
  const by = {};
  for (const category of ['orchestrator', 'worker']) {
    for (const entry of readCensus(rows, category).values()) {
      total += entry.total; pickable += entry.by.pickable || 0; limited += entry.limited;
      for (const key of Object.keys(entry.by)) { by[key] = (by[key] || 0) + entry.by[key]; }
    }
  }
  const top = REASONS.filter((reason) => reason.key !== 'pickable' && by[reason.key])
    .sort((a, b) => by[b.key] - by[a.key]).slice(0, 2).map((reason) => by[reason.key] + ' ' + reason.label.toLowerCase());
  return {orchestrator: scope === 'paid' ? nextRoute(rows, at, 'orchestrator') : null,
    worker: nextRoute(rows, at, scope === 'paid' ? 'paid' : 'free'),
    pickable: {count: pickable, of: total}, skipped: {count: total - pickable, text: top.join(' · ')},
    limited: {count: limited}};
});
// ---- Why routes are picked or skipped, across the lanes of the page ----
context.handlebars.registerHelper('modelReasons', function(rows) {
  rows = configured(rows);
  const by = {};
  const providers = {};
  let total = 0;
  let limited = 0;
  for (const category of ['orchestrator', 'worker']) {
    for (const entry of readCensus(rows, category).values()) {
      total += entry.total; limited += entry.limited;
      for (const key of Object.keys(entry.by)) {
        by[key] = (by[key] || 0) + entry.by[key];
        providers[key] = providers[key] || new Map();
        providers[key].set(entry.provider, (providers[key].get(entry.provider) || 0) + entry.by[key]);
      }
    }
  }
  const peak = Math.max(1, ...Object.values(by));
  const list = REASONS.filter((reason) => by[reason.key]).map((reason) => ({
    key: reason.key, label: reason.label, tone: reason.tone, hint: reason.hint, count: by[reason.key],
    width: Math.max(2, Math.round(by[reason.key] * 1000 / peak) / 10),
    who: Array.from(providers[reason.key].entries()).sort((a, b) => b[1] - a[1]).slice(0, 4)
      .map(([provider, count]) => who(provider).name + ' ' + count).join(' · ')}));
  return {list: list, total: total, limited: limited, empty: total === 0};
});

