.gx{font:12px/1.3 Inter,system-ui,sans-serif;color:#e6e8ee;container-type:inline-size;width:100%}
.gx *{box-sizing:border-box}
.gx .in{background:#181a20;border:1px solid #262932;border-radius:8px;padding:10px 12px}
.gx header{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:0 0 4px}
.gx header b{font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:#c9ccd3}
.gx header span{font-size:11px;color:#8b8f99}
.gx ol{list-style:none;margin:0;padding:0}
.gx .ic{flex:none;width:20px;height:20px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700}
.gx .good{--c:#5fb878}.gx .ok{--c:#5b9bd5}.gx .warn{--c:#e0a03a}.gx .bad{--c:#e66767}.gx .out{--c:#e66767}.gx .held{--c:#b08cf0}.gx .trust{--c:#c678dd}.gx .unk,.gx .idle{--c:#8b8f99}
.gx .bar{display:block;position:relative;height:8px;border-radius:4px;background:#2a2d36;overflow:hidden}
.gx .pa{position:relative;flex:none;width:76px;height:8px;border-radius:4px;background:#2a2d36}
.gx .pa:after{content:"";position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:#9aa1ad}
.gx .pa.unk,.gx .hatch{background:repeating-linear-gradient(135deg,#2a2d36 0 4px,#3a3e49 4px 8px)}
.gx .pa.unk:after{display:none}
.gx .pa i{position:absolute;top:0;bottom:0;border-radius:3px;background:var(--c)}
.gx .pill{font-style:normal;font-size:10px;font-weight:700;letter-spacing:.03em;text-transform:uppercase;padding:1px 6px;border-radius:9px;color:#111;background:var(--c);white-space:nowrap;flex:none}
.gx .pill.unk,.gx .pill.idle{color:#d6d9e0;background:#3a3e49}
.gx .lane li.r{padding:7px 0;border-top:1px solid #23262e}
.gx .lane li.r:first-child{border-top:0}
.gx .lane .n{flex:none;width:16px;text-align:right;font-weight:700;color:#8b8f99;font-variant-numeric:tabular-nums;line-height:20px}
.gx .lane li.first .n{color:#5fb878}
.gx .lane .l4{margin-top:4px;font-size:11px}
.gx .lane .cal{font-size:10.5px;padding:0 6px;border-radius:9px;border:1px solid var(--c);color:var(--c)}
.gx .lane .cal.unk{border-style:dashed}
.gx .lane .bd{flex:1;min-width:0}
.gx .lane .l1,.gx .lane .l2,.gx .lane .l3,.gx .lane .l4{display:flex;flex-wrap:wrap;align-items:center;gap:2px 7px;min-width:0}
.gx .lane .l1{min-height:20px}
.gx .lane .l1 .pa{flex:none;width:56px}
.gx .lane .nm{font-size:13px;font-weight:600;flex:none}
.gx .lane .md{flex:1 1 12ch;min-width:0;overflow-wrap:anywhere;color:#8b8f99}
.gx .lane .big{flex:none;margin-left:auto;font-size:14px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--c)}
.gx .lane .big.unk,.gx .lane .big.held{font-size:11px;font-weight:500;color:#8b8f99;font-style:italic}
.gx .lane .l2{margin-top:4px;font-size:11px;color:#9aa1ad}
.gx .lane .pt{flex:0 0 auto}
.gx .lane .pv{font-weight:700;color:var(--c);font-variant-numeric:tabular-nums}
.gx .lane .wn{flex:0 1 auto;min-width:0;margin-left:auto;color:#8b8f99}
.gx .lane .sw{display:none}
.gx .lane .l3{margin-top:5px;font-size:11px;color:#9aa1ad}
.gx .lane .cb{flex:1;min-width:0;display:flex;gap:2px;height:8px}
.gx .lane .cb i{display:block;height:100%;min-width:3px;border-radius:2px;background:var(--c);flex:0 1 auto}
.gx .lane .cb i.idle{background:#4a4e5a}
.gx .lane .ct{flex:none;color:#aeb6c3;font-variant-numeric:tabular-nums}
.gx .lane .cs{margin-top:3px;font-size:10.5px;color:#8b8f99}
.gx .lane .cs .lm{color:#a9b4ff}
.gx .lane .more,.gx .lane .none{margin-top:6px;padding-top:6px;border-top:1px solid #23262e;font-size:11px;color:#8b8f99}
.gx .lane .none{border:0;padding:14px 0}
.gx .tiles{display:grid;grid-template-columns:repeat(12,1fr);gap:8px}
.gx .tile{grid-column:span 6;min-width:0;background:#181a20;border:1px solid #262932;border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;justify-content:center;gap:3px}
.gx .tile.pick{grid-column:span 6}
.gx .tile.wide{grid-column:span 12}
.gx .tile.half{grid-column:span 6}
.gx .tile .k{font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:#8b8f99}
.gx .tile .v{font-size:24px;font-weight:700;line-height:1.15;color:var(--c,#e6e8ee);overflow-wrap:anywhere}
.gx .tile .v .ic{display:inline-flex;vertical-align:middle;margin-right:7px}
.gx .tile .v small{font-size:13px;font-weight:500;color:#8b8f99}
.gx .tile .s{font-size:11px;color:#9aa1ad;overflow-wrap:anywhere}
.gx .tile.stat .v{font-size:34px}
.gx .why li.w{padding:7px 0;border-top:1px solid #23262e}
.gx .why li.w:first-child{border-top:0}
.gx .why .t{display:flex;align-items:baseline;gap:8px}
.gx .why .nm{font-weight:600;font-size:13px;color:var(--c)}
.gx .why .ct{margin-left:auto;font-size:18px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--c)}
.gx .why .bar{margin-top:4px;height:6px}
.gx .why .bar i{display:block;height:100%;border-radius:3px;background:var(--c)}
.gx .why .bar i.idle{background:#4a4e5a}
.gx .why .hn{margin-top:3px;font-size:10.5px;color:#8b8f99}
.gx .why .hn b{color:#aeb6c3;font-weight:500}
.gx .why li.w.nodata .nm{color:#8b8f99;font-weight:500}
.gx .why li.w.nodata .ct{font-size:12px;font-weight:500;font-style:italic;color:#8b8f99}
.gx .why .ft{margin-top:6px;padding-top:6px;border-top:1px solid #23262e;font-size:11px;color:#9aa1ad}
.gx .why .ft b{color:#a9b4ff}
.dt-row:has(>.gx){flex:1 0 auto;display:flex;flex-direction:column}
.dt-row>.gx{flex:1 0 auto;display:flex;flex-direction:column}
.gx>.in{flex:1;display:flex;flex-direction:column}
.gx>.tiles{flex:1;grid-auto-rows:1fr}
.gx .lane .ls,.gx .lane .ls>ol,.gx .in>ol{display:contents}
.gx .in>header,.gx .ls>header{flex:none}
.gx .more,.gx .ft{flex:none}
.gx .lane li.r,.gx .prov li.pr,.gx .frees li.fr,.gx .why li.w{flex:1 1 auto;display:flex;flex-direction:column;justify-content:center}
.gx .lane .rw{display:flex;align-items:flex-start;gap:8px}
@container (min-width:900px){
 .gx .tile .k{font-size:12px}.gx .tile .s{font-size:12.5px}
 .gx .tile .v{font-size:30px}.gx .tile.stat .v{font-size:46px}.gx .tile .v small{font-size:15px}
 .gx .tile .v .ic{width:26px;height:26px;font-size:15px}
}
@container (max-width:640px){
 .gx .tile.pick,.gx .tile.wide{grid-column:span 12}
 .gx .tiles{gap:6px}
 .gx .tile{padding:5px 10px;gap:0}
 .gx .tile .k{font-size:10px;line-height:1.2}
 .gx .tile .v{font-size:16px;line-height:1.15}.gx .tile.stat .v{font-size:22px;line-height:1.1}
 .gx .tile .s{font-size:10.5px;line-height:1.2}
 .gx .tile .v .ic{width:16px;height:16px;font-size:10px;margin-right:6px}
}
@container (max-width:420px){
 .gx .lane .pt .long{display:none}
 .gx .lane .pa{width:56px}
 .gx .lane .l1 .pa{display:none}
 .gx .lane li.out .pt{display:none}
 .gx .lane .pill:not(.good){display:none}.gx .lane .sw{display:inline;color:var(--c);font-weight:600}
 .gx .lane .warn .sw{display:none}
}

options.helpers:
// Presentation only. Every number is a collector gauge; this code orders,
// words and colours them and never turns a missing reading into a number.
const PROVIDERS = {
  claude: {name: 'Claude', icon: '✳', bg: '#d97757', fg: '#fff'},
  codex: {name: 'Codex', icon: '⊛', bg: '#e8e8e8', fg: '#111'},
  ollama: {name: 'Ollama', icon: '◉', bg: '#f2f2f2', fg: '#111'},
  'opencode-go': {name: 'OpenCode Go', icon: '{}', bg: '#2b2f3a', fg: '#7dd3fc'},
  antigravity: {name: 'Antigravity', icon: 'A', bg: 'linear-gradient(135deg,#4f8cff,#c86bfa)', fg: '#fff'},
  grok: {name: 'Grok', icon: '⊘', bg: '#000', fg: '#fff'},
  commandCode: {name: 'Command Code', icon: 'C', bg: '#2b2f3a', fg: '#e6e8ee'},
  opencode: {name: 'OpenCode Zen', icon: 'O', bg: '#2b2f3a', fg: '#e6e8ee'},
  'cloudflare-workers-ai': {name: 'Cloudflare'},
  'kilo-keyed': {name: 'Kilo (keyed)', icon: 'K'},
  openrouter: {name: 'OpenRouter'},
  nvidia: {name: 'NVIDIA'},
  ovh: {name: 'OVH'},
  zai: {name: 'Zai'},
  deepseek: {name: 'DeepSeek'},
  orcarouter: {name: 'Orcarouter'},
};
function who(id) {
  const known = PROVIDERS[id] || {};
  const text = String(id || '');
  return {
    name: known.name || text.split(/[-_\s]+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
    icon: known.icon || text.charAt(0).toUpperCase(),
    bg: known.bg || '#2b2f3a',
    fg: known.fg || '#e6e8ee',
  };
}
function num(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function round1(value) { return Math.round(value * 10) / 10; }
// The span until a reset: minutes, hours, then days.
function span(seconds) {
  if (seconds <= 0) { return 'now'; }
  const minutes = Math.max(1, Math.round(seconds / 60));
  if (minutes < 60) { return minutes + 'm'; }
  if (minutes < 2880) { return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm'; }
  return round1(minutes / 1440) + 'd';
}
function back(reset, now) {
  if (reset === null || reset === undefined) { return ''; }
  const left = span(reset - now);
  return left === 'now' ? 'back now' : 'back in ' + left;
}
// The share that is left: a half point is kept, a whole reading has no zero.
function share(left) {
  const tenths = Math.round(left * 1000);
  return (tenths % 10 === 0 ? String(tenths / 10) : (tenths / 10).toFixed(1)) + '%';
}
function signed(points) {
  const value = round1(Math.abs(points));
  return (points > 0 ? '+' : points < 0 ? '−' : '') + value;
}
function clock(seconds) {
  const moment = new Date(seconds * 1000);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad = (n) => String(n).padStart(2, '0');
  return moment.getUTCDate() + ' ' + months[moment.getUTCMonth()] + ' ' + pad(moment.getUTCHours()) + ':' + pad(moment.getUTCMinutes()) + 'Z';
}
// A pace band to a tone and a word. spent is out of quota, never "on pace".
const PACE = {
  ahead: {tone: 'good', word: 'ahead of pace'},
  on_pace: {tone: 'ok', word: 'on pace'},
  behind: {tone: 'warn', word: 'behind pace'},
  far_behind: {tone: 'bad', word: 'overspent'},
  spent: {tone: 'out', word: 'out of quota'},
};
// The bar of Paced Availability: centre line is on pace, right is ahead and
// left is overspent. A missing reading gets no bar and no number.
function paBar(points) {
  if (points === null) { return {known: false, left: 50, width: 0, side: 'unk'}; }
  const half = Math.min(100, Math.abs(points)) / 2;
  return {known: true, left: points < 0 ? 50 - half : 50, width: Math.max(half, 1.5), side: points < 0 ? 'neg' : 'pos'};
}

// Who fills a reading the collector does not publish yet: the sub-issue of the epic.
const FILLED_BY = {claude: '#465', commandCode: '#466'};
function filledBy(provider) { return FILLED_BY[provider] ? ' · ' + FILLED_BY[provider] : ''; }

function ordinal(n) {
  const rest = n % 100;
  const suffix = rest >= 11 && rest <= 13 ? 'th' : ({1: 'st', 2: 'nd', 3: 'rd'}[n % 10] || 'th');
  return n + suffix;
}
// The model id the calibration series names: a path separator and an at sign become an underscore.
function calibrationKey(provider, model) { return provider + '|' + String(model || '').replace(/[@/]/g, '_'); }

// ---- Routes: one row per selected route of a lane --------------------------
const ROUTE_FIELDS = {position: 'position', left: 'left', pace: 'pace', resetAt: 'resetAt'};
function readRoutes(rows) {
  const routes = new Map();
  for (const row of rows || []) {
    if (!row || !row.category || !row.provider || !row.model || !ROUTE_FIELDS[row.field]) { continue; }
    const key = [row.category, row.provider, row.model, row.effort || ''].join('|');
    let route = routes.get(key);
    if (!route) { route = {labels: row, n: {}}; routes.set(key, route); }
    route.n[row.field] = num(row.value);
  }
  return Array.from(routes.values());
}
// What a route is, in the order the picker ranks it, and why.
function routeView(route, now) {
  const l = route.labels;
  const n = route.n;
  const inferred = l.window === 'inferred';
  // An inferred window that has seen no limit is not 100%: it is unknown.
  const left = n.left === undefined || n.left === null || (inferred && n.left >= 1) ? null : n.left;
  const pace = PACE[l.pace_state] || null;
  const pa = n.pace === undefined || n.pace === null ? null : n.pace;
