}
function censusView(entry) {
  if (!entry) { return null; }
  const parts = REASONS.filter((reason) => entry.by[reason.key]).map((reason) => ({
    key: reason.key, label: reason.label, tone: reason.tone, count: entry.by[reason.key],
    pct: Math.round(entry.by[reason.key] * 1000 / entry.total) / 10}));
  const skipped = parts.filter((part) => part.key !== 'pickable');
  return {total: entry.total, pickable: entry.by.pickable || 0, parts: parts, limited: entry.limited,
    partial: entry.limited > 0 && entry.limited < entry.total,
    text: (entry.by.pickable || 0) + ' of ' + entry.total + ' pickable',
    skipped: skipped.map((part) => part.count + ' ' + part.label.toLowerCase()).join(' · ')};
}

// ---- Lanes: one row per provider, its selected route and why its other routes are skipped ----
const NOW = (value) => (num(value) || 0) / 1000;
function providerRoute(view, census, account, calibration, now) {
  if (view) {
    const routed = {...view, census: censusView(census)};
    if (calibration) { routed.calib = calibration; }
    if (account && !view.out) {
      // The provider's account says it is spent: show that, with the window's reset, not the route's own reading.
      return {...routed, kind: 'out', out: true, word: 'Out of quota', capacity: '0% left', leftText: '0%', left: 0,
        paKnown: false, paceLong: false, when: account.reset ? back(account.reset, now) : '',
        acctNote: 'account window spent' + (account.estimated ? ' · estimated' : '')};
    }
    return routed;
  }
  const stub = censusView(census);
  const top = stub && stub.parts.filter((part) => part.key !== 'pickable').sort((a, b) => b.count - a.count)[0];
  const identity = who(census.provider);
  // Routes that can be picked but none is selected: unknown, not out. Only a provider with nothing pickable is out.
  const open = !!(stub && stub.pickable > 0);
  // A spent account blocks every route of the provider, selected or not.
  if (account) {
    return {provider: census.provider, name: identity.name, icon: identity.icon, bg: identity.bg, fg: identity.fg,
      model: '', noRoute: true, paceLong: false, kind: 'out', out: true, word: 'Out of quota', capacity: '', leftText: '',
      paKnown: false, paText: '', paLeft: 50, paWidth: 0, paSide: 'unk', when: account.reset ? back(account.reset, now) : '',
      acctNote: 'account window spent' + (account.estimated ? ' · estimated' : ''), position: 1e9, next: false, census: stub};
  }
  return {provider: census.provider, name: identity.name, icon: identity.icon, bg: identity.bg, fg: identity.fg,
    model: '', noRoute: true, paceLong: false, kind: open ? 'unk' : 'out', out: !open,
    word: open ? '' : (top ? 'All ' + top.label.toLowerCase() : 'No route'),
    capacity: open ? 'no route selected' : '', leftText: '', paKnown: false, paText: '', paLeft: 50, paWidth: 0, paSide: 'unk', when: '',
    position: 1e9, next: false, census: stub};
}
// The orchestrator is the picker's first orchestrator: the other candidates it lists are not orchestrators.
function configured(rows) {
  const list = (rows || []).filter((row) => row && row.category === 'orchestrator' && row.field === 'position');
  if (!list.length) { return rows; }
  const first = list.reduce((a, b) => (num(b.value) < num(a.value) ? b : a));
  return rows.filter((row) => !row || row.category !== 'orchestrator' || row.provider === first.provider);
}
function laneProviders(rows, now, lane) {
  const category = lane === 'orchestrator' ? 'orchestrator' : 'worker';
  const selected = new Map();
  // One route per provider: the picker's own order decides when two routes of a provider are selected.
  for (const route of readRoutes((rows || []).filter((row) => row && row.category === category))) {
    const view = routeView(route, now);
    const known = selected.get(route.labels.provider);
    if (!known || view.position < known.position) { selected.set(route.labels.provider, view); }
  }
  const census = readCensus(rows, category);
  const accounts = lane === 'free' ? readAccounts(rows) : new Map();
  const calibration = lane === 'free' ? readCalibration(rows) : new Map();
  // A provider whose every route is in the public pool has no approved worker: it is counted, never listed.
  const listed = Array.from(census.keys()).filter((provider) => {
    const entry = census.get(provider);
    return lane !== 'free' || selected.has(provider) || entry.by.public !== entry.total;
  });
  const providers = new Set([...selected.keys(), ...listed]);
  const list = Array.from(providers).map((provider) => {
    const view = selected.get(provider);
    const state = view ? calibration.get(calibrationKey(provider, view.rawModel)) : null;
    return providerRoute(view, census.get(provider), accounts.get(provider),
      state ? {...CALIBRATION[state], state: state} : null, now);
  });
  list.sort((a, b) => a.position - b.position || (b.census ? b.census.total : 0) - (a.census ? a.census.total : 0)
    || (a.name < b.name ? -1 : 1));
  const first = list.findIndex((view) => !view.noRoute && !view.out && view.kind !== 'held');
  // The rank is the picker's own position among all workers, so a paid worker reads 4th when free routes go first.
  return list.map((view, index) => ({...view, rank: view.position < 1e9 ? view.position : '·', first: index === first,
    next: index === first && view.position === 1, many: !!(view.census && view.census.total > 1),
    pace: !view.noRoute && !view.acctNote && (view.paKnown || (view.kind !== 'unk' && (view.paceLong || !!view.when)))}));
}
context.handlebars.registerHelper('modelRows', function(rows, now, lane, limit) {
  const all = laneProviders(configured(rows), NOW(now), lane);
  const shown = limit ? all.slice(0, limit) : all;
  return {rows: shown, more: all.length - shown.length, count: all.length};
});
// ---- Summary tiles ----
function nextRoute(rows, now, lane) {
  const view = laneProviders(rows, now, lane).find((entry) => entry.first);
  if (!view) { return null; }
  // A paid worker is tried after the free routes: say where the picker puts it.
  const order = lane === 'paid' && view.position > 1 && view.position < 1e9 ? 'tried ' + ordinal(view.position) + ', after the free routes' : '';
  return {name: view.name, icon: view.icon, bg: view.bg, fg: view.fg, model: view.model, kind: view.kind,
    detail: [view.word, view.capacity, view.when, order].filter(Boolean).join(' · ')};
}
context.handlebars.registerHelper('modelSummary', function(rows, now, scope) {
  rows = configured(rows);
  const at = NOW(now);
  const census = new Map();
  let total = 0;
  let pickable = 0;
  let limited = 0;
  const by = {};
  for (const category of ['orchestrator', 'worker']) {
    for (const entry of readCensus(rows, category).values()) {
      total += entry.total; pickable += entry.by.pickable || 0; limited += entry.limited;
      for (const key of Object.keys(entry.by)) { by[key] = (by[key] || 0) + entry.by[key]; }
    }
  }
  const top = REASONS.filter((reason) => reason.key !== 'pickable' && by[reason.key])
    .sort((a, b) => by[b.key] - by[a.key]).slice(0, 2).map((reason) => by[reason.key] + ' ' + reason.label.toLowerCase());
  return {orchestrator: scope === 'paid' ? nextRoute(rows, at, 'orchestrator') : null,
    worker: nextRoute(rows, at, scope === 'paid' ? 'paid' : 'free'),
    pickable: {count: pickable, of: total}, skipped: {count: total - pickable, text: top.join(' · ')},
    limited: {count: limited}};
});
// ---- Why routes are picked or skipped, across the lanes of the page ----
context.handlebars.registerHelper('modelReasons', function(rows) {
  rows = configured(rows);
  const by = {};
  const providers = {};
  let total = 0;
  let limited = 0;
  for (const category of ['orchestrator', 'worker']) {
    for (const entry of readCensus(rows, category).values()) {
      total += entry.total; limited += entry.limited;
      for (const key of Object.keys(entry.by)) {
        by[key] = (by[key] || 0) + entry.by[key];
        providers[key] = providers[key] || new Map();
        providers[key].set(entry.provider, (providers[key].get(entry.provider) || 0) + entry.by[key]);
      }
    }
  }
  const peak = Math.max(1, ...Object.values(by));
  const list = REASONS.filter((reason) => by[reason.key]).map((reason) => ({
    key: reason.key, label: reason.label, tone: reason.tone, hint: reason.hint, count: by[reason.key],
    width: Math.max(2, Math.round(by[reason.key] * 1000 / peak) / 10),
    who: Array.from(providers[reason.key].entries()).sort((a, b) => b[1] - a[1]).slice(0, 4)
      .map(([provider, count]) => who(provider).name + ' ' + count).join(' · ')}));
  return {list: list, total: total, limited: limited, empty: total === 0};
});

options.afterRender:
const root=context.element.querySelector('section.quality');
if(root&&!root.dataset.pagerBound){
 root.dataset.pagerBound='true';
 // Grafana sanitizes form controls before this hook. Build fixed trusted
 // controls through DOM APIs; keep HTML sanitization enabled.
 const doc=root.ownerDocument,controls=root.querySelector('[data-quality-controls]');
 const make=(tag,key,text)=>{const node=doc.createElement(tag);node.setAttribute(key,'');if(text)node.textContent=text;return node};
 const search=make('input','data-quality-filter');search.type='search';search.placeholder='Filter model or effort';search.setAttribute('aria-label','Filter model or effort');controls.append(search);
 const label=doc.createElement('label'),toggle=make('input','data-quality-all');label.className='quality-toggle';toggle.type='checkbox';label.append(toggle,doc.createTextNode(' All models'));controls.append(label);
 const pager=doc.createElement('div');pager.append(make('button','data-quality-prev','Previous'),make('span','data-quality-range'),make('button','data-quality-next','Next'));controls.append(pager);
 root.querySelectorAll('[data-quality-expand-label]').forEach(label=>{const button=make('button','data-quality-expand',label.textContent);button.className='quality-expand';button.type='button';button.setAttribute('aria-expanded','false');label.replaceWith(button)});
 const rows=[...root.querySelectorAll('tbody tr.quality-model-row')];
 const filter=root.querySelector('[data-quality-filter]'),all=root.querySelector('[data-quality-all]');
 const prev=root.querySelector('[data-quality-prev]'),next=root.querySelector('[data-quality-next]');
 const expanded=new Set();let page=0,lastWidth=0;
 function show(){
  const term=filter.value.toLowerCase().trim();
  const matches=rows.filter(row=>(all.checked||row.dataset.selected==='true')&&row.dataset.qualitySearch.toLowerCase().includes(term));
  const has=name=>matches.some(row=>row.dataset[name]==='true');
  const columns={aa:has('hasAa'),observed:has('hasObserved'),passes:has('hasObserved'),time:has('hasTime'),tokens:has('hasTokens'),quota:has('hasQuota'),findings:has('hasFindings'),source:has('hasObserved')};
  for(const [column,visible]of Object.entries(columns))root.querySelectorAll('[data-col="'+column+'"]').forEach(cell=>cell.hidden=!visible);
  root.querySelectorAll('.quality-merge').forEach(cell=>cell.hidden=!has('hasMerged'));
  root.querySelector('th[data-col="passes"]').textContent=has('hasMerged')?'Pass / merged':'Pass';
  root.querySelector('[data-quality-evidence-note]').hidden=has('hasObserved');
  root.querySelector('[data-quality-empty]').hidden=matches.length>0;
  const size=root.getBoundingClientRect().width<650?3:15;
  page=Math.max(0,Math.min(page,Math.ceil(matches.length/size)-1));
  rows.forEach(row=>{row.hidden=true});
  root.querySelectorAll('.quality-effort-detail').forEach(row=>row.hidden=true);
  matches.slice(page*size,(page+1)*size).forEach((row,index)=>{
   row.hidden=false;row.querySelector('[data-quality-rank]').textContent=page*size+index+1;const detail=row.nextElementSibling;
   if(detail&&detail.classList.contains('quality-effort-detail'))detail.hidden=!expanded.has(row.dataset.qualityKey);
  });
  root.querySelector('[data-quality-range]').textContent=matches.length?`${page*size+1}–${Math.min((page+1)*size,matches.length)} of ${matches.length}`:'No matching models';
  prev.disabled=page===0;next.disabled=(page+1)*size>=matches.length;
 }
 filter.addEventListener('input',()=>{page=0;show()});all.addEventListener('change',()=>{page=0;show()});
 prev.addEventListener('click',()=>{page--;show()});next.addEventListener('click',()=>{page++;show()});
 root.querySelectorAll('[data-quality-expand]').forEach(button=>button.addEventListener('click',()=>{
  const key=button.closest('tr').dataset.qualityKey;
  if(expanded.has(key))expanded.delete(key);else expanded.add(key);
  button.setAttribute('aria-expanded',String(expanded.has(key)));show();
 }));
 const observer=new ResizeObserver(()=>{if(!root.isConnected){observer.disconnect();return}const width=root.getBoundingClientRect().width;if(width!==lastWidth){lastWidth=width;show()}});
 observer.observe(root);show();
 return ()=>observer.disconnect();
}

options.helpers:
function qualityRows(rows){
 const groups=new Map();
 for(const row of rows||[]){
  if(!row.model||!row.provider)continue;
  const key=[row.provider,row.model,row.effort_option,row.effort].join('|');
  if(!groups.has(key))groups.set(key,{...row,values:{}});
  if(row.value!==null&&row.value!==undefined&&Number.isFinite(Number(row.value)))groups.get(key).values[row.field]=Number(row.value);
 }
 const fmt=x=>x===undefined?'—':String(Math.round(x*10)/10);
 const tok=x=>x===undefined?'—':x>=1e9?fmt(x/1e9)+'B':x>=1e6?fmt(x/1e6)+'M':x>=1e3?fmt(x/1e3)+'k':String(Math.round(x));
 const date=x=>!x?'—':new Date(x*1000).toISOString().slice(0,10);
 return [...groups.values()].sort((a,b)=>(a.values.rank??1e9)-(b.values.rank??1e9)).map(r=>{
  const v=r.values;return {...r,representative:v.representative===1,selected:r.selection==='selected',selectionReason:r.selection_reason||'',modelRank:v.model_rank??1e9,hasObserved:(v.n??0)>0,hasAA:v.aa!==undefined,hasTime:v.median_seconds!==undefined||v.seconds_per_pass!==undefined,hasTokens:v.tokens_per_pass!==undefined,hasQuota:v.quota_per_pass!==undefined,hasFindings:v.review_findings!==undefined,hasMerged:(v.merge_n??0)>0,rank:v.rank??'—',overall:fmt(v.overall),aa:fmt(v.aa),observed:fmt(v.observed),n:v.n??0,
   provisional:(v.n??0)<5,passes:v.n?v.passed+'/'+v.n:'no evidence yet',
   merges:v.merge_n?v.merged+'/'+v.merge_n:'—',
   median:v.median_seconds===undefined?'—':fmt(v.median_seconds/60)+' min',
   timePerPass:v.seconds_per_pass===undefined?'—':fmt(v.seconds_per_pass/60)+' min',
   tokens:v.tokens_per_pass===undefined?'—':tok(v.tokens_per_pass),quota:fmt(v.quota_per_pass),findings:fmt(v.review_findings),
   date:date(v.date),aaDate:v.aa!==undefined&&r.aa_date?String(r.aa_date).slice(0,10)+(r.aa_state==='stale'?' · stale':''):'',
   weight:v.observed_weight===undefined?'—':Math.round(v.observed_weight*100)+'%',
   bar:v.overall===undefined?0:Math.max(0,Math.min(100,v.overall)),
   evidenceMissing:r.evidence_state==='producer_unavailable'||r.evidence_state==='unreadable'};
 });
}
context.handlebars.registerHelper('qualityRows',qualityRows);
context.handlebars.registerHelper('qualityModels',function(rows){
 const groups=new Map();
 for(const row of qualityRows(rows)){
  const key=row.provider+'|'+row.model;
  if(!groups.has(key))groups.set(key,[]);
  groups.get(key).push(row);
 }
 return [...groups.entries()].map(([key,variants])=>{
  const best=variants.find(row=>row.representative)||variants[0];
  const measured=variants.filter(row=>row.n>0);
  const signature=row=>JSON.stringify(['n','passed','observed','merged','merge_n','median_seconds','seconds_per_pass','tokens_per_pass','quota_per_pass','review_findings'].map(field=>row.values[field]??null));
  const different=measured.length>1&&new Set(measured.map(signature)).size>1;
  return {...best,key,efforts:different?measured:[],compare:different,
   search:[best.provider,best.model,best.selection,best.selectionReason,...variants.map(row=>row.effort)].join(' ')};
 }).sort((a,b)=>a.modelRank-b.modelRank);
});

